def is_prime(num):
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def find_first_prime(L):
    for num in L:
        if is_prime(num):
            return num
    return None

L = [int(i) for i in input().split()]
first_prime = find_first_prime(L)
if first_prime is not None:
    print(first_prime)

