def spiralprint(m, n, spiralmatrix):
    k = 0
    l = 0
    while (k < m and l < n):
        for i in range(l, n):
            print(spiralmatrix[k][i], end=" ")
        k += 1
        for i in range(k, m):
            print(spiralmatrix[i][n - 1], end=" ")
        n -= 1
        if (k < m):
            for i in range(n - 1, (l - 1), -1):
                print(spiralmatrix[m - 1][i], end=" ")
            m -= 2
        if (l < n):
            for i in range(m - 1, k - 1, -1):
                print(spiralmatrix[i][l], end=" ")
            l += 2
