import calendar
def count_something(year, month):
    x,y=calendar.monthrange(year,month)
    last_day=y
    count=0
    for day in range(1, last_day+1):
        if calendar.weekday(year,month,day)<5 :
            count+=1

    return count

def test(word):

    new_word = ''

    for ch in word:

        if ch>='a' and ch<='z':

            temp = ord(ch)
            temp = temp - 32
            temp = chr(temp)
            new_word = new_word + temp

    return new_word
